# Use 8-connectivity flood fill starting from first 2
visited = [[False]*15 for _ in range(9)]
to_fill = [[0]*15 for _ in range(9)]

def flood_fill(point, grid):
    r, c = point
    q = deque([point])
    visited[r][c] = True

    while q:
        curr_r, curr_c = q.popleft()
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < 9 and 0 <= nc < 15 and not visited[nr][nc]:
                    visited[nr][nc] = True
                    q.append((nr, nc))

